+}
+
+* { box-sizing: border-box; }
+html { -webkit-text-size-adjust: 100%; }
+body { margin: 0; background: var(--bg); color: var(--ink); font-family: var(--sans); font-weight: 430; font-size: 16px; line-height: 1.5; -webkit-font-smoothing: antialiased; }
+a { color: inherit; text-decoration: none; }
+button, input { font: inherit; }
+button { color: inherit; background: none; border: 0; cursor: pointer; }
+img { display: block; max-width: 100%; }
+::selection { background: var(--lime); color: var(--ink); }
+
+.app { display: flex; min-height: 100vh; }
+.mono { font-family: var(--mono); text-transform: uppercase; letter-spacing: 0.11em; }
+
+.sidebar { width: var(--side-w); flex: none; position: sticky; top: 0; height: 100vh; overflow-y: auto; background: var(--side); border-right: 1px solid var(--line); padding: 22px 16px 20px; display: flex; flex-direction: column; gap: 4px; z-index: 1600; }
+.logo { display: flex; align-items: center; gap: 10px; padding: 4px 8px 20px; }
+.bolt { width: 30px; height: 30px; border-radius: 8px; background: var(--ink); display: grid; place-items: center; flex: none; color: var(--lime); }
+.logo b { font-weight: 700; font-size: 18px; letter-spacing: -0.04em; }
+.logo span:last-child { font-style: italic; font-weight: 400; font-size: 18px; color: var(--ink-2); letter-spacing: -0.02em; }
+.navi, .cat { display: flex; align-items: center; gap: 12px; border-radius: 11px; color: var(--ink-2); transition: background 0.18s, color 0.18s; user-select: none; }
+.navi { padding: 9px 12px; font-size: 14.5px; font-weight: 480; }
+.navi:hover, .cat:hover { background: rgba(18, 18, 16, 0.055); color: var(--ink); }
+.navi.active, .cat.active { background: rgba(18, 18, 16, 0.07); color: var(--ink); font-weight: 560; }
+.navi svg { width: 18px; height: 18px; stroke-width: 1.7; }
+.new { margin-left: auto; font-family: var(--mono); font-size: 8px; letter-spacing: 0.08em; background: var(--lime); color: var(--ink); padding: 2px 6px; border-radius: 5px; font-weight: 600; }
+.side-label { font-family: var(--mono); font-size: 9.5px; letter-spacing: 0.13em; text-transform: uppercase; color: var(--ink-3); padding: 0 12px; margin: 20px 0 7px; }
+.cat { width: 100%; padding: 7px 12px; font-size: 14px; text-align: left; }
+.cat .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--ink); flex: none; opacity: 0.55; }
+.cat.active .dot { background: var(--lime); opacity: 1; box-shadow: 0 0 0 3px rgba(201, 250, 70, 0.3); }
+.side-foot { margin-top: auto; padding-top: 20px; }
+.promo-card { background: var(--lime); color: var(--ink); border-radius: 14px; padding: 15px 16px; position: relative; overflow: hidden; }
+.promo-card h4 { font-size: 14px; font-weight: 650; letter-spacing: -0.02em; margin: 0 0 4px; max-width: 78%; line-height: 1.2; }
+.promo-card p { font-size: 11.5px; color: rgba(18,18,16,.7); margin: 0; }
+.promo-card svg { position: absolute; top: 13px; right: 13px; width: 26px; height: 26px; }
+.side-cta { display: flex; align-items: center; gap: 12px; margin-top: 14px; }
+.btn-ink { background: var(--ink); color: #fff; font-family: var(--mono); font-size: 11px; letter-spacing: 0.09em; text-transform: uppercase; padding: 11px 16px; border-radius: 10px; transition: 0.22s; flex: 1; text-align: center; }
+.btn-ink:hover { background: var(--lime); color: var(--ink); }
+.free { font-size: 12.5px; color: var(--ink-3); white-space: nowrap; }
+.side-legal { display: flex; align-items: center; gap: 8px; margin-top: 18px; padding: 0 4px; font-size: 11.5px; color: var(--ink-3); flex-wrap: wrap; }
+.stars { margin-left: auto; font-family: var(--mono); font-size: 10px; background: rgba(18,18,16,.06); padding: 4px 7px; border-radius: 7px; color: var(--ink); }
+
+.main { flex: 1; min-width: 0; padding-bottom: 120px; }
+.mtop { display: none; }
+.topbar { position: sticky; top: 0; z-index: 1200; background: rgba(237,236,230,.76); backdrop-filter: blur(18px) saturate(1.25); border-bottom: 1px solid var(--line-2); }
+.filterbar { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 20px 28px 12px; }
+.ftabs, .fsort { display: flex; align-items: center; gap: 7px; overflow-x: auto; scrollbar-width: none; }
+.ftabs::-webkit-scrollbar, .fsort::-webkit-scrollbar { display: none; }
+.ftab, .sortbtn { white-space: nowrap; border: 1px solid var(--line); background: rgba(255,255,255,.45); transition: .18s; }
+.ftab { display: inline-flex; align-items: center; gap: 7px; padding: 10px 14px; border-radius: 999px; font-size: 13.5px; font-weight: 520; }
+.ftab svg { width: 15px; height: 15px; stroke-width: 1.8; }
+.ftab.active, .sortbtn.active { background: var(--ink); color: #fff; border-color: var(--ink); }
+.sortbtn { padding: 9px 12px; border-radius: 10px; font-family: var(--mono); font-size: 10.5px; letter-spacing: .09em; text-transform: uppercase; color: var(--ink-2); }
+.searchbar { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .28s var(--ease); }
+.searchbar.open { grid-template-rows: 1fr; }
+.searchbar .inner { overflow: hidden; display: flex; align-items: center; gap: 12px; margin: 0 28px; border-top: 1px solid transparent; }
+.searchbar.open .inner { border-top-color: var(--line-2); padding: 12px 0 16px; }
+.searchbar svg { width: 18px; height: 18px; color: var(--ink-3); flex: none; }
+.searchbar input { width: 100%; border: 0; outline: 0; background: transparent; color: var(--ink); font-size: 15px; }
+.gallery { padding: 16px 28px 40px; }
+.masonry { column-width: 238px; column-gap: 14px; }
+.tile { break-inside: avoid; display: inline-block; width: 100%; margin: 0 0 14px; border-radius: 18px; overflow: hidden; position: relative; background: var(--card); box-shadow: 0 1px 0 rgba(0,0,0,.03); animation: fadeUp .5s var(--ease) both; }
+.media { aspect-ratio: var(--ar); background: #d9d8d1; overflow: hidden; }
