+.tile:hover .media img { transform: scale(1.04); }
+.fb { width: 100%; height: 100%; background: var(--ink); color: var(--lime); display: grid; place-items: center; }
+.fb-mark { font-size: 4rem; font-weight: 800; letter-spacing: -0.08em; }
+.savedmark { position: absolute; top: 12px; left: 12px; z-index: 4; width: 30px; height: 30px; border-radius: 9px; display: none; place-items: center; background: var(--lime); color: var(--ink); box-shadow: 0 10px 20px rgba(0,0,0,.15); }
+.tile.saved .savedmark { display: grid; }
+.ov { position: absolute; inset: 0; padding: 13px; display: flex; flex-direction: column; justify-content: space-between; background: linear-gradient(to bottom, rgba(0,0,0,.48), transparent 34%, rgba(0,0,0,.68)); color: #fff; opacity: 0; transition: opacity .22s; }
+.tile:hover .ov, .tile:focus-within .ov { opacity: 1; }
+.ov__top, .ov__row { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
+.model { font-family: var(--mono); font-size: 9.5px; letter-spacing: .1em; text-transform: uppercase; background: rgba(255,255,255,.9); color: var(--ink); padding: 6px 8px; border-radius: 999px; }
+.bm { width: 32px; height: 32px; border-radius: 9px; background: rgba(255,255,255,.92); display: grid; place-items: center; color: var(--ink); }
+.bm.on { background: var(--lime); }
+.ov h3 { margin: 0 0 10px; font-size: 1.04rem; line-height: 1.08; letter-spacing: -0.035em; text-shadow: 0 2px 16px rgba(0,0,0,.35); }
+.price { font-family: var(--mono); font-weight: 600; }
+.price.free { color: var(--lime); }
+.add { display: inline-flex; align-items: center; gap: 6px; background: var(--lime); color: var(--ink); border-radius: 999px; padding: 8px 11px; font-family: var(--mono); font-size: 10px; letter-spacing: .08em; text-transform: uppercase; font-weight: 600; }
+.add svg { width: 12px; height: 12px; }
+.empty { width: 100%; padding: 90px 20px; text-align: center; color: var(--ink-2); }
+.empty .big { font-size: 1.4rem; font-weight: 600; margin-bottom: 8px; color: var(--ink); }
+@keyframes fadeUp { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
+
+.dock { position: fixed; bottom: 22px; left: calc(50% + var(--side-w) / 2); transform: translateX(-50%); z-index: 1400; display: flex; gap: 5px; padding: 8px; background: rgba(248,247,243,.72); backdrop-filter: blur(18px) saturate(1.4); border: 1px solid var(--line); border-radius: 21px; box-shadow: 0 16px 44px rgba(18,18,16,.16); }
+.dock button, .dock a { position: relative; width: 44px; height: 44px; border-radius: 13px; display: grid; place-items: center; color: var(--ink-2); transition: .18s; }
+.dock .active, .dock a.active { background: var(--ink); color: #fff; }
+.dock svg { width: 20px; height: 20px; stroke-width: 1.7; }
+.cbadge { position: absolute; top: 5px; right: 5px; min-width: 16px; height: 16px; padding: 0 4px; border-radius: 8px; background: var(--lime); color: var(--ink); font-family: var(--mono); font-size: 9px; font-weight: 600; display: grid; place-items: center; transform: scale(1); }
+.toast { position: fixed; bottom: 90px; left: calc(50% + var(--side-w)/2); transform: translate(-50%, 150%); background: var(--ink); color: #fff; font-family: var(--mono); font-size: 12px; letter-spacing: .04em; padding: 13px 20px; border-radius: 11px; z-index: 2200; display: flex; align-items: center; gap: 10px; box-shadow: 0 12px 32px rgba(0,0,0,.3); transition: transform .45s var(--ease); }
+.toast.show { transform: translate(-50%,0); }
+.toast .d { width: 7px; height: 7px; border-radius: 50%; background: var(--lime); }
+.scrim { position: fixed; inset: 0; background: rgba(0,0,0,.45); z-index: 1550; display: none; }
+.scrim.show { display: block; }
+
+.detail-page, .cart-page, .analytics-page { padding: 32px; max-width: 1120px; margin: 0 auto; }
+.panel { background: rgba(255,255,255,.55); border: 1px solid var(--line); border-radius: 20px; padding: 24px; }
+.detail-grid { display: grid; grid-template-columns: minmax(260px, 1.1fr) minmax(260px, .9fr); gap: 24px; }
+.detail-image { border-radius: 20px; overflow: hidden; background: #d9d8d1; aspect-ratio: var(--ar); }
+.detail-image img { width: 100%; height: 100%; object-fit: cover; }
+.detail h1, .analytics-page h1, .cart-page h1 { margin: 0 0 14px; font-size: clamp(2rem, 5vw, 4.2rem); line-height: .95; letter-spacing: -0.07em; }
+.detail .desc { color: var(--ink-2); max-width: 58ch; }
+.stat-row, .cart-row { display: flex; justify-content: space-between; gap: 16px; border-top: 1px solid var(--line); padding: 14px 0; }
+.cart-row { align-items: center; }
+.cart-row img { width: 74px; height: 92px; object-fit: cover; border-radius: 12px; background: #d9d8d1; }
+.cart-main { display: flex; align-items: center; gap: 14px; min-width: 0; }
+.summary { max-width: 420px; margin-left: auto; }
+.metric-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin: 18px 0 24px; }
+.metric { background: rgba(255,255,255,.55); border: 1px solid var(--line); border-radius: 16px; padding: 16px; }
+.metric .k, .table .k { font-family: var(--mono); color: var(--ink-3); font-size: 10px; text-transform: uppercase; letter-spacing: .1em; }
+.metric .v { font-size: 1.8rem; font-weight: 700; letter-spacing: -0.04em; }
+.table { background: rgba(255,255,255,.5); border: 1px solid var(--line); border-radius: 18px; overflow: hidden; margin: 16px 0; }
+.table div { display: grid; grid-template-columns: 1.4fr .7fr .7fr; gap: 16px; padding: 13px 16px; border-top: 1px solid var(--line-2); }
+.table div:first-child { border-top: 0; }
+
+@media (max-width: 960px) {
