+  .detail-grid { grid-template-columns: 1fr; }
+  .metric-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
+  .detail-page, .cart-page, .analytics-page { padding: 18px; }
+}
+
+@media (max-width: 520px) {
+  .masonry { column-width: 164px; column-gap: 10px; }
+  .tile { margin-bottom: 10px; border-radius: 15px; }
