+}
+
+function rows<T>(database: Database, sql: string, params: unknown[] = []): T[] {
+  const stmt = database.prepare(sql, params)
+  const out: T[] = []
+  while (stmt.step()) out.push(stmt.getAsObject() as T)
+  stmt.free()
+  return out
+}
