+CASE WHEN f.prompt_id IS NULL THEN 0 ELSE 1 END AS isFavorite,
+CASE WHEN ci.prompt_id IS NULL THEN 0 ELSE 1 END AS inCart,
+ROUND((p.popularity * 0.58) + (p.views * 0.025) + (p.featured * 18) - (julianday('2026-07-08') - julianday(p.created_at)) * 0.42, 2) AS rankScore
+FROM prompts p
+JOIN creators c ON c.id=p.creator_id JOIN categories cat ON cat.id=p.category_id
+LEFT JOIN favorites f ON f.prompt_id=p.id AND f.user_id='u1'
+LEFT JOIN cart_items ci ON ci.prompt_id=p.id AND ci.user_id='u1'`
+
+function mapPrompt(row: Record<string, unknown>): PromptCard {
+  return { ...row, priceCents: Number(row.priceCents), isFree: Boolean(row.isFree), featured: Boolean(row.featured), popularity: Number(row.popularity), tags: String(row.tags).split(','), isFavorite: Boolean(row.isFavorite), inCart: Boolean(row.inCart), rankScore: Number(row.rankScore) } as PromptCard
+}
+
+export async function getStorefront(filters: StorefrontFilters = {}): Promise<StorefrontData> {
+  const database = await getDb()
+  const where: string[] = []
+  const params: unknown[] = []
+  if (filters.q) { where.push('(lower(p.title) LIKE ? OR lower(p.summary) LIKE ? OR lower(p.tags) LIKE ?)'); const q = `%${filters.q.toLowerCase()}%`; params.push(q, q, q) }
+  if (filters.model && filters.model !== 'All') { where.push('p.model = ?'); params.push(filters.model) }
+  if (filters.category && filters.category !== 'all') { where.push('cat.id = ?'); params.push(filters.category) }
+  if (filters.favorites) where.push('f.prompt_id IS NOT NULL')
+  if (filters.freeOnly) where.push('p.is_free = 1')
+  const order = filters.sort === 'Newest' ? 'p.created_at DESC' : filters.sort === 'Popular' ? 'p.popularity DESC, rankScore DESC' : 'rankScore DESC'
+  const promptRows = rows<Record<string, unknown>>(database, `${promptSelect} ${where.length ? `WHERE ${where.join(' AND ')}` : ''} ORDER BY ${order}`, params).map(mapPrompt)
+  const countRow = rows<Record<string, number>>(database, `SELECT COUNT(*) total, SUM(is_free) free, SUM(CASE WHEN is_free=0 THEN 1 ELSE 0 END) paid, SUM(featured) featured,(SELECT COUNT(*) FROM favorites WHERE user_id='u1') favorites,(SELECT COUNT(*) FROM cart_items WHERE user_id='u1') cart FROM prompts`)[0]
+  const categories = rows<{ id: string; name: string; color: string; count: number }>(database, `SELECT cat.id,cat.name,cat.color,COUNT(p.id) count FROM categories cat LEFT JOIN prompts p ON p.category_id=cat.id GROUP BY cat.id ORDER BY cat.name`)
