+  const order = filters.sort === 'Newest' ? 'p.created_at DESC' : filters.sort === 'Popular' ? 'p.popularity DESC, rankScore DESC' : 'rankScore DESC'
+  const promptRows = rows<Record<string, unknown>>(database, `${promptSelect} ${where.length ? `WHERE ${where.join(' AND ')}` : ''} ORDER BY ${order}`, params).map(mapPrompt)
+  const countRow = rows<Record<string, number>>(database, `SELECT COUNT(*) total, SUM(is_free) free, SUM(CASE WHEN is_free=0 THEN 1 ELSE 0 END) paid, SUM(featured) featured,(SELECT COUNT(*) FROM favorites WHERE user_id='u1') favorites,(SELECT COUNT(*) FROM cart_items WHERE user_id='u1') cart FROM prompts`)[0]
+  const categories = rows<{ id: string; name: string; color: string; count: number }>(database, `SELECT cat.id,cat.name,cat.color,COUNT(p.id) count FROM categories cat LEFT JOIN prompts p ON p.category_id=cat.id GROUP BY cat.id ORDER BY cat.name`)
+  return { prompts: promptRows, counts: { total: Number(countRow.total), free: Number(countRow.free), paid: Number(countRow.paid), featured: Number(countRow.featured), favorites: Number(countRow.favorites), cart: Number(countRow.cart) }, categories, models: ['All', 'GPT-4o', 'Claude', 'Midjourney', 'Flux'] }
