+
+export async function toggleFavorite(promptId: string) {
+  const database = await getDb()
+  const exists = rows(database, `SELECT 1 FROM favorites WHERE user_id='u1' AND prompt_id=?`, [promptId]).length > 0
+  database.run(exists ? `DELETE FROM favorites WHERE user_id='u1' AND prompt_id=?` : `INSERT INTO favorites(user_id,prompt_id) VALUES('u1',?)`, [promptId])
+  persistDb()
+  return { isFavorite: !exists }
+}
+
+export async function addToCart(promptId: string) {
+  const database = await getDb()
+  database.run(`INSERT OR IGNORE INTO cart_items(user_id,prompt_id) VALUES('u1',?)`, [promptId])
+  persistDb()
+  return getCart()
+}
+
+export async function removeFromCart(promptId: string) {
+  const database = await getDb()
+  database.run(`DELETE FROM cart_items WHERE user_id='u1' AND prompt_id=?`, [promptId])
+  persistDb()
+  return getCart()
+}
+
+export async function getCart(): Promise<CartSummary> {
+  const database = await getDb()
+  const items = rows<Record<string, unknown>>(database, `${promptSelect} WHERE ci.prompt_id IS NOT NULL ORDER BY p.title`).map(mapPrompt)
+  const total = rows<{ subtotalCents: number; feeCents: number; totalCents: number }>(database, `SELECT COALESCE(SUM(p.price_cents),0) subtotalCents, ROUND(COALESCE(SUM(p.price_cents),0)*0.05) feeCents, COALESCE(SUM(p.price_cents),0)+ROUND(COALESCE(SUM(p.price_cents),0)*0.05) totalCents FROM cart_items ci JOIN prompts p ON p.id=ci.prompt_id WHERE ci.user_id='u1'`)[0]
