+  const categoryRevenue = rows<Analytics['categoryRevenue'][number]>(database, `SELECT cat.name category,SUM(oi.price_cents) revenueCents,COUNT(*) units FROM order_items oi JOIN categories cat ON cat.id=oi.category_id GROUP BY cat.id ORDER BY revenueCents DESC`)
+  const dailySales = rows<Analytics['dailySales'][number]>(database, `SELECT created_at day,SUM(total_cents) revenueCents,COUNT(*) orders FROM orders GROUP BY created_at ORDER BY created_at`)
+  const totals = rows<Analytics['totals']>(database, `SELECT SUM(total_cents) revenueCents,COUNT(*) orders,ROUND((SELECT COUNT(*) FROM order_items)*1.0 / (SELECT SUM(audience) FROM creators),4) conversionRate,ROUND(AVG(total_cents)) averageOrderValueCents FROM orders`)[0]
+  return { creatorRevenue, categoryRevenue, dailySales, totals }
+}
